import hmac
import hashlib
import os
import sys

# Set 4 Challenge 31 - Generate HMAC and store in .hmac files
# Slightly modified from code generated by Claude

def compute_hmac(path):
    key = b"anotverysecurekey"
    h = hmac.new(key, digestmod=hashlib.sha1)
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

def precompute(filename):
    # Compute the HMAC of a file and store it in <filename>.hmac
    # Possibly unsafe way to handle filename, but this will do for simplicity
    if filename is None or not os.path.isfile(filename):
        sys.exit(f"File not found: {filename}")
    with open(filename + ".hmac", "w") as f:
        f.write(compute_hmac(filename))
    print(f"Stored HMAC for {filename}")

if len(sys.argv) != 2:
    print("Generate hmac for input file")
    print("Argument: <filename>")
    exit()

filename = sys.argv[1]
precompute(filename)
